const source = $('Get RSS Source1').first().json;
const xml = $input.first().json.data || $input.first().json.body || $input.first().json;

const itemsRaw = xml.match(/<item>[\s\S]*?<\/item>/g) || [];

function extract(tag, str) {
  const m = str.match(new RegExp(`<${tag}>([\\s\\S]*?)<\\/${tag}>`));
  if (!m) return '';
  return m[1].replace('<![CDATA[', '').replace(']]>', '').trim();
}

const items = itemsRaw.map((raw) => ({
  title: extract('title', raw),
  link: extract('link', raw),
  pubDate: extract('pubDate', raw),
  description: extract('description', raw),
}));

// Instead of stopping the workflow when the feed has no items,
// pass a flag through so downstream nodes can build a "no update" email.
if (items.length === 0) {
  return [{
    json: {
      source_id: source.id,
      source_name: source.name,
      no_articles_found: true
    }
  }];
}

const getDate = (item) => {
  const t = new Date(item.pubDate).getTime();
  return Number.isNaN(t) ? 0 : t;
};

items.sort((a, b) => getDate(b) - getDate(a));
const latest = items[0];

return [{
  json: {
    source_id: source.id,
    source_name: source.name,
    title: latest.title || 'Untitled article',
    url: latest.link || '',
    published_at: latest.pubDate || null,
    summary: latest.description || ''
  }
}];

const article = $json;
const parsed = $('Parse & Keep Latest1').first().json;
const source = parsed.source_name;

const escapeHtml = (s = '') => String(s)
  .replaceAll('&', '&amp;').replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;').replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');

// No new article: either the feed had nothing, or the latest item
// was already in the database (Insert If New returned 0 rows).
const hasNewArticle = !parsed.no_articles_found && !!article.id;

if (!hasNewArticle) {
  const html = `
    <h2>Daily News Update</h2>
    <h3>${escapeHtml(source)}</h3>
    <p>Today we don't have any update.</p>
    <hr><p style="font-size:12px;color:#666">Generated automatically by n8n News Monitor.</p>`;

  return {
    json: {
      article_id: null,
      subject: `News Update - ${source} (No new articles)`,
      html
    }
  };
}

const title = escapeHtml(article.title);
const summary = escapeHtml(article.summary || '');
const url = escapeHtml(article.url);
const publishedAt = article.published_at
  ? new Date(article.published_at).toLocaleString('en-GB', { timeZone: 'Asia/Yerevan' })
  : 'Date unavailable';

const html = `
  <h2>Daily News Update</h2>
  <h3>${escapeHtml(source)}</h3>
  <p><strong>${title}</strong></p>
  <p>${publishedAt}</p>
  ${summary ? `<p>${summary}</p>` : ''}
  <p><a href="${url}">Read full article</a></p>
  <hr><p style="font-size:12px;color:#666">Generated automatically by n8n News Monitor.</p>`;

return { json: { article_id: article.id, subject: `News Update - ${source}`, html } };
